    #[derive(Debug, Default)]
    struct HttpOverlapControlState {
        enabled: bool,
        target_session: Option<usize>,
        lock_attempts: usize,
        lock_contentions: usize,
        entries: usize,
        permits: usize,
    }

    #[derive(Debug, Default)]
    struct HttpOverlapControl {
        state: Mutex<HttpOverlapControlState>,
        changed: Condvar,
    }

    impl HttpOverlapControl {
        fn begin(&self, target_session: usize) -> HttpOverlapControlGuard<'_> {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.enabled = true;
            state.target_session = Some(target_session);
            state.lock_attempts = 0;
            state.lock_contentions = 0;
            state.entries = 0;
            state.permits = 0;
            HttpOverlapControlGuard { control: self }
        }

        fn record_lock_attempt(&self, session: usize) -> bool {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            if !state.enabled || state.target_session != Some(session) {
                return false;
            }
            state.lock_attempts += 1;
            self.changed.notify_all();
            true
        }

        fn record_lock_contention(&self, session: usize) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            if state.enabled && state.target_session == Some(session) {
                state.lock_contentions += 1;
                self.changed.notify_all();
            }
        }

        fn enter_and_wait(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            if !state.enabled {
                return;
            }
            state.entries += 1;
            self.changed.notify_all();
            while state.enabled && state.permits == 0 {
                state = self
                    .changed
                    .wait(state)
                    .expect("HTTP overlap control poisoned while waiting");
            }
            state.permits = state.permits.saturating_sub(1);
        }

        fn wait_for_entries(&self, target: usize, timeout: Duration) -> bool {
            let state = self.state.lock().expect("HTTP overlap control poisoned");
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| state.entries < target)
                .expect("HTTP overlap control poisoned while observing entries");
            state.entries >= target
        }

        fn wait_for_lock_attempts(&self, target: usize, timeout: Duration) -> bool {
            let state = self.state.lock().expect("HTTP overlap control poisoned");
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| state.lock_attempts < target)
                .expect("HTTP overlap control poisoned while observing lock attempts");
            state.lock_attempts >= target
        }

        fn wait_for_lock_contentions(&self, target: usize, timeout: Duration) -> bool {
            let state = self.state.lock().expect("HTTP overlap control poisoned");
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| state.lock_contentions < target)
                .expect("HTTP overlap control poisoned while observing lock contention");
            state.lock_contentions >= target
        }

        fn release_one(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.permits = state.permits.saturating_add(1);
            self.changed.notify_all();
        }

        fn disable(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.enabled = false;
            state.target_session = None;
            state.permits = 0;
            self.changed.notify_all();
        }
    }

    struct HttpOverlapControlGuard<'a> {
        control: &'a HttpOverlapControl,
    }

    impl Drop for HttpOverlapControlGuard<'_> {
        fn drop(&mut self) {
            self.control.disable();
        }
    }

    type HttpOverlapWorker = thread::JoinHandle<Result<(), String>>;
    type HttpOverlapWorkerResult = thread::Result<Result<(), String>>;

    struct HttpOverlapWorkers<'a> {
        control: &'a HttpOverlapControl,
        handles: Vec<HttpOverlapWorker>,
    }

    impl<'a> HttpOverlapWorkers<'a> {
        fn new(control: &'a HttpOverlapControl) -> Self {
            Self {
                control,
                handles: Vec::new(),
            }
        }

        fn push(&mut self, handle: HttpOverlapWorker) {
            self.handles.push(handle);
        }

        fn join_all(mut self) -> Vec<HttpOverlapWorkerResult> {
            self.control.disable();
            self.handles
                .drain(..)
                .map(thread::JoinHandle::join)
                .collect()
        }
    }

    impl Drop for HttpOverlapWorkers<'_> {
        fn drop(&mut self) {
            self.control.disable();
            for handle in self.handles.drain(..) {
                let _ = handle.join();
            }
        }
    }

    fn http_overlap_metrics() -> &'static HttpOverlapMetrics {
        HTTP_OVERLAP_METRICS.get_or_init(HttpOverlapMetrics::default)
    }

    fn http_overlap_lock() -> &'static Mutex<()> {
        HTTP_OVERLAP_LOCK.get_or_init(|| Mutex::new(()))
    }

    fn http_overlap_control() -> &'static HttpOverlapControl {
        HTTP_OVERLAP_CONTROL.get_or_init(HttpOverlapControl::default)
    }

    pub(super) fn record_http_session_lock_attempt(session: usize) -> bool {
        http_overlap_control().record_lock_attempt(session)
    }

    pub(super) fn record_http_session_lock_contention(session: usize) {
        http_overlap_control().record_lock_contention(session);
    }

    pub(super) fn record_live_http_listener_wait() {
        LIVE_HTTP_LISTENER_WAITS.fetch_add(1, Ordering::AcqRel);
    }

    pub(super) fn record_live_http_connection_read_wait() {
        LIVE_HTTP_CONNECTION_READ_WAITS.fetch_add(1, Ordering::AcqRel);
    }

    fn live_http_listener_wait_count() -> usize {
        LIVE_HTTP_LISTENER_WAITS.load(Ordering::Acquire)
    }

    fn live_http_connection_read_wait_count() -> usize {
        LIVE_HTTP_CONNECTION_READ_WAITS.load(Ordering::Acquire)
    }

    async fn wait_for_live_http_probe(
        cx: &Cx,
        before: usize,
        probe: fn() -> usize,
    ) -> Result<(), String> {
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while probe() <= before {
            cx.checkpoint()
                .map_err(|error| format!("live HTTP probe caller stopped: {error}"))?;
            asupersync::time::timeout_at(
                deadline,
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
            )
            .await
            .map_err(|_| live_http_test_timeout("live HTTP probe"))?;
        }
        Ok(())
    }

    async fn wait_for_live_http_test_result<T>(receiver: Receiver<T>) -> Result<T, String> {
        let cx = Cx::current().expect("the test runtime must install an ambient Cx while polling");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        loop {
            match receiver.try_recv() {
                Ok(result) => return Ok(result),
                Err(TryRecvError::Disconnected) => {
                    panic!("live HTTP test task exited without reporting its result");
                }
                Err(TryRecvError::Empty) => {
                    asupersync::time::timeout_at(
                        deadline,
                        asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
                    )
                    .await
                    .map_err(|_| live_http_test_timeout("live HTTP test result"))?;
                }
            }
        }
    }

    fn run_live_http_test<F, Fut>(operation: F)
    where
        F: FnOnce(Cx) -> Fut + Send + 'static,
        Fut: Future<Output = Result<(), String>> + Send + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live HTTP test reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live HTTP test runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .handle()
            .try_spawn_with_cx(move |cx| async move {
                let _ = sender.send(operation(cx).await);
            })
            .expect("live HTTP test task must be admitted");

        let result = runtime
            .block_on(wait_for_live_http_test_result(receiver))
            .unwrap();
        result.unwrap();
    }

    fn run_live_modern_pump<R>(server: Server, recv: R, responses: Arc<LiveModernResponses>) -> i32
    where
        R: FnMut(&Cx, &AtomicBool) -> Result<JsonRpcMessage, TransportError> + Send + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live modern test reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live modern test runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .handle()
            .try_spawn_with_cx(move |cx| async move {
                let dispatch_cx = cx.clone();
                let result = match cx.spawn_blocking(move |pump_cx| {
                    server.run_loop_pump_with_policy(
                        &pump_cx,
                        &dispatch_cx,
                        recv,
                        move |_send_cx, message| {
                            responses.record(message.clone());
                            Ok(())
                        },
                        Arc::new(|_| {}),
                        "live-modern-test",
                        false,
                        None,
                        true,
                    )
                }) {
                    Ok(mut pump) => pump
                        .join(&cx)
                        .await
                        .map_err(|error| format!("live modern pump join failed: {error:?}")),
                    Err(error) => Err(format!("live modern pump admission failed: {error}")),
                };
                let _ = sender.send(result);
            })
            .expect("live modern test task must be admitted");

        runtime
            .block_on(wait_for_live_http_test_result(receiver))
            .expect("live modern pump timed out")
            .expect("live modern pump must complete")
    }

    fn run_live_split_transport<R, S>(server: Server, recv: R, send: S) -> Result<(), String>
    where
        R: TransportRecvHalf + Send + 'static,
        S: TransportSendHalf + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live split transport reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live split transport runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .handle()
            .try_spawn_with_cx(move |cx| async move {
                let dispatch_cx = cx.clone();
                let result = match cx.spawn_blocking(move |pump_cx| {
                    server.run_split_transport_returning_with_dispatch_cx(
                        &pump_cx,
                        &dispatch_cx,
                        recv,
                        send,
                    )
                }) {
                    Ok(mut pump) => pump
                        .join(&cx)
                        .await
                        .map_err(|error| format!("live split transport join failed: {error:?}"))
                        .and_then(|result| result.map_err(|error| error.to_string())),
                    Err(error) => Err(format!("live split transport admission failed: {error}")),
                };
                let _ = sender.send(result);
            })
            .expect("live split transport task must be admitted");

        runtime.block_on(wait_for_live_http_test_result(receiver))?
    }

    async fn live_http_exchange(address: SocketAddr, request: Vec<u8>) -> Result<Vec<u8>, String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP exchange");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let mut stream = asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client connection"))?
            .map_err(|error| format!("live HTTP client connect failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.write_all(&request))
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client request write"))?
            .map_err(|error| format!("live HTTP client write failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.flush())
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client request flush"))?
            .map_err(|error| format!("live HTTP client flush failed: {error}"))?;
        let mut response = Vec::new();
        read_live_http_to_end(&mut stream, &mut response, "live HTTP client response EOF").await?;
        Ok(response)
    }

    fn live_http_post(
        path_and_query: &str,
        body: &[u8],
        extra_headers: &[(&str, &str)],
    ) -> Vec<u8> {
        let mut request = format!(
            "POST {path_and_query} HTTP/1.1\r\nHost: loopback\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n",
            body.len()
        );
        for (name, value) in extra_headers {
            request.push_str(name);
            request.push_str(": ");
            request.push_str(value);
            request.push_str("\r\n");
        }
        request.push_str("\r\n");
        let mut request = request.into_bytes();
        request.extend_from_slice(body);
        request
    }

    fn live_http_response_body(response: &[u8]) -> Result<&[u8], String> {
        response
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
            .map(|offset| &response[offset + 4..])
            .ok_or_else(|| "live HTTP response omitted its header terminator".to_string())
    }

    async fn read_live_http_until(
        stream: &mut AsyncTcpStream,
        received: &mut Vec<u8>,
        needle: &[u8],
    ) -> Result<(), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP SSE reads");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while !received
            .windows(needle.len())
            .any(|window| window == needle)
        {
            if received.len() > 64 * 1024 {
                return Err("live HTTP SSE response exceeded the test bound".to_string());
            }
            let mut chunk = [0_u8; 2048];
            let read = asupersync::time::timeout_at(deadline, stream.read(&mut chunk))
                .await
                .map_err(|_| live_http_test_timeout("live HTTP SSE response"))?
                .map_err(|error| format!("live HTTP SSE read failed: {error}"))?;
            if read == 0 {
                return Err("live HTTP SSE connection closed before expected event".to_string());
            }
            received.extend_from_slice(&chunk[..read]);
        }
        Ok(())
    }

    async fn read_live_http_to_end(
        stream: &mut AsyncTcpStream,
        received: &mut Vec<u8>,
        operation: &str,
    ) -> Result<(), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP EOF reads");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        asupersync::time::timeout_at(deadline, stream.read_to_end(received))
            .await
            .map_err(|_| live_http_test_timeout(operation))?
            .map_err(|error| format!("{operation} failed: {error}"))?;
        Ok(())
    }

    async fn open_live_legacy_http_session(
        address: SocketAddr,
    ) -> Result<(AsyncTcpStream, String, Vec<u8>), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for legacy HTTP SSE setup");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let mut stream = asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE connection"))?
            .map_err(|error| format!("legacy HTTP SSE connect failed: {error}"))?;
        let request = format!(
            "GET /sse HTTP/1.1\r\nHost: {address}\r\nAccept: text/event-stream\r\nConnection: keep-alive\r\n\r\n"
        );
        asupersync::time::timeout_at(deadline, stream.write_all(request.as_bytes()))
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE request write"))?
            .map_err(|error| format!("legacy HTTP SSE write failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.flush())
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE request flush"))?
            .map_err(|error| format!("legacy HTTP SSE flush failed: {error}"))?;

        let mut received = Vec::new();
        let endpoint_prefix = format!("data: http://{address}/messages?session_id=");
        read_live_http_until(&mut stream, &mut received, endpoint_prefix.as_bytes()).await?;
        let received_text = std::str::from_utf8(&received)
            .map_err(|error| format!("legacy HTTP SSE endpoint was not UTF-8: {error}"))?;
        let session_id = received_text
            .split_once(&endpoint_prefix)
            .and_then(|(_, remainder)| remainder.split_whitespace().next())
            .ok_or_else(|| "legacy HTTP SSE endpoint omitted its session identifier".to_string())?
            .to_owned();
        Ok((stream, session_id, received))
    }

    async fn wait_for_live_http_legacy_admission(
        cx: &Cx,
        session: &LiveHttpSession,
        request_id: &RequestId,
    ) -> Result<(), String> {
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while !session.cancellation.admissions.contains(request_id) {
            cx.checkpoint()
                .map_err(|error| format!("legacy HTTP admission wait stopped: {error}"))?;
            asupersync::time::timeout_at(
                deadline,
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
            )
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP request admission"))?;
        }
        Ok(())
    }

    fn reset_http_overlap_metrics() {
        let metrics = http_overlap_metrics();
        metrics.current.store(0, Ordering::SeqCst);
        metrics.max.store(0, Ordering::SeqCst);
    }

