    struct LiveLegacyCancellationTool {
        started: Arc<AtomicBool>,
        observed_cancellation: Arc<AtomicBool>,
    }

    impl ToolHandler for LiveLegacyCancellationTool {
        fn definition(&self) -> Tool {
            Tool {
                name: "live_legacy_cancellation_tool".to_owned(),
                description: Some(
                    "Proves exact legacy cancellation reaches the live handler".to_owned(),
                ),
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, _arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            self.started.store(true, Ordering::Release);
            let deadline = Instant::now() + Duration::from_secs(1);
            while !ctx.is_cancelled() && Instant::now() < deadline {
                std::thread::yield_now();
            }
            if ctx.is_cancelled() {
                self.observed_cancellation.store(true, Ordering::Release);
                return Err(McpError::request_cancelled());
            }
            Err(McpError::internal_error(
                "exact legacy cancellation did not reach the live handler",
            ))
        }
    }

    #[derive(Default)]
    struct LiveLegacyRequestGate {
        entered: AtomicBool,
        released: AtomicBool,
    }

    impl LiveLegacyRequestGate {
        fn enter(&self, ctx: &McpContext) -> McpResult<()> {
            self.entered.store(true, Ordering::Release);
            let deadline = Instant::now() + Duration::from_secs(2);
            while !self.released.load(Ordering::Acquire) && Instant::now() < deadline {
                if ctx.is_cancelled() {
                    return Err(McpError::request_cancelled());
                }
                thread::yield_now();
            }
            if self.released.load(Ordering::Acquire) {
                Ok(())
            } else {
                Err(McpError::internal_error(
                    "bounded legacy HTTP request gate was not released",
                ))
            }
        }

        fn release(&self) {
            self.released.store(true, Ordering::Release);
        }
    }

    struct LiveLegacyRequestGateRelease {
        gate: Arc<LiveLegacyRequestGate>,
    }

    impl Drop for LiveLegacyRequestGateRelease {
        fn drop(&mut self) {
            self.gate.release();
        }
    }

    struct LiveHttpSessionMutexHold {
        release: Option<std::sync::mpsc::SyncSender<()>>,
        worker: Option<thread::JoinHandle<Result<(), String>>>,
    }

    impl LiveHttpSessionMutexHold {
        fn new(session: Arc<LiveHttpSession>) -> Result<Self, String> {
            let (started_sender, started_receiver) = sync_channel(1);
            let (release_sender, release_receiver) = sync_channel(1);
            let worker = thread::spawn(move || {
                let _session = session
                    .session
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                started_sender
                    .send(())
                    .map_err(|_| "legacy HTTP session holder lost its test owner".to_string())?;
                release_receiver
                    .recv_timeout(Duration::from_secs(2))
                    .map_err(|_| "legacy HTTP session holder release timed out".to_string())?;
                Ok(())
            });
            let mut hold = Self {
                release: Some(release_sender),
                worker: Some(worker),
            };
            if started_receiver
                .recv_timeout(Duration::from_secs(2))
                .is_err()
            {
                let _ = hold.release();
                return Err("legacy HTTP session holder did not acquire the mutex".to_string());
            }
            Ok(hold)
        }

        fn release(&mut self) -> Result<(), String> {
            if let Some(sender) = self.release.take() {
                sender.send(()).map_err(|_| {
                    "legacy HTTP session holder release was disconnected".to_string()
                })?;
            }
            let Some(worker) = self.worker.take() else {
                return Ok(());
            };
            worker
                .join()
                .map_err(|_| "legacy HTTP session holder panicked".to_string())?
        }
    }

    impl Drop for LiveHttpSessionMutexHold {
        fn drop(&mut self) {
            let _ = self.release();
        }
    }

