    #[test]
    fn live_http_loopback_dispatches_modern_json_over_a_real_socket() {
        run_live_http_test(|cx| async move {
            let bound = Server::new("live-modern-http", "1.0.0")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live modern HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live modern HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let request = JsonRpcRequest::new(
                SERVER_DISCOVER_METHOD,
                Some(serde_json::json!({
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                801_i64,
            );
            let body = serde_json::to_vec(&request)
                .map_err(|error| format!("modern wire request did not serialize: {error}"))?;
            let request = live_http_post(
                "/mcp",
                &body,
                &[
                    ("Accept", "application/json"),
                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                    ("Mcp-Method", SERVER_DISCOVER_METHOD),
                ],
            );
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let response = live_http_exchange(address, request).await;
                    caller_cx.cancel_with(CancelKind::User, Some("modern loopback complete"));
                    response
                })
                .map_err(|error| format!("modern loopback client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let response = client
                .join(&cx)
                .await
                .map_err(|error| format!("modern loopback client failed: {error:?}"))??;
            serve.map_err(|error| format!("modern loopback server failed: {error}"))?;

            let response = std::str::from_utf8(&response)
                .map_err(|error| format!("modern loopback response was not UTF-8: {error}"))?;
            if !response.starts_with("HTTP/1.1 200") {
                return Err(format!(
                    "modern loopback response status was unexpected: {response}"
                ));
            }
            if !response
                .to_ascii_lowercase()
                .contains("\r\nconnection: close\r\n")
            {
                return Err(format!(
                    "single-request HTTP response did not declare connection closure: {response}"
                ));
            }
            let response: JsonRpcResponse = serde_json::from_slice(live_http_response_body(
                response.as_bytes(),
            )?)
            .map_err(|error| format!("modern loopback JSON-RPC response was invalid: {error}"))?;
            if response.id != Some(801_i64.into()) || response.error.is_some() {
                return Err(format!(
                    "modern loopback request was not dispatched: {response:?}"
                ));
            }
            if response.result.as_ref().and_then(|result| {
                result["_meta"][fastmcp_protocol::SERVER_DISCOVER_SERVER_INFO_META_KEY]["name"]
                    .as_str()
            }) != Some("live-modern-http")
            {
                return Err(format!(
                    "modern loopback discovery result was unexpected: {response:?}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_protocol_admission_preserves_jsonrpc_when_only_version_header_differs() {
        run_live_http_test(|cx| async move {
            let bound = Server::new("live-http-protocol-admission", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("protocol-admission HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("protocol-admission HTTP address failed: {error}"))?;
            let request = JsonRpcRequest::new(
                SERVER_DISCOVER_METHOD,
                Some(serde_json::json!({
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                814_i64,
            );
            let body = serde_json::to_vec(&request)
                .map_err(|error| format!("protocol-admission request did not serialize: {error}"))?;
            let accepted = live_http_post(
                "/mcp",
                &body,
                &[
                    ("Accept", "application/json"),
                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                    ("Mcp-Method", SERVER_DISCOVER_METHOD),
                ],
            );
            // This has the same JSON-RPC body and all the same HTTP headers
            // except the final protocol-version mirror.
            let rejected = live_http_post(
                "/mcp",
                &body,
                &[
                    ("Accept", "application/json"),
                    ("MCP-Protocol-Version", "2025-11-25"),
                    ("Mcp-Method", SERVER_DISCOVER_METHOD),
                ],
            );
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let result = async {
                        let accepted = live_http_exchange(address, accepted).await?;
                        let rejected = live_http_exchange(address, rejected).await?;
                        Ok::<_, String>((accepted, rejected))
                    }
                    .await;
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("protocol-admission loopback complete"),
                    );
                    result
                })
                .map_err(|error| format!("protocol-admission client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let (accepted, rejected) = client
                .join(&cx)
                .await
                .map_err(|error| format!("protocol-admission client failed: {error:?}"))??;
            serve.map_err(|error| format!("protocol-admission server failed: {error}"))?;

            if !accepted.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "matching final protocol-version request was not accepted: {accepted:?}"
                ));
            }
            let accepted: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&accepted)?).map_err(|error| {
                    format!("accepted protocol-admission response was invalid: {error}")
                })?;
            if accepted.id != Some(814_i64.into()) || accepted.error.is_some() {
                return Err(format!(
                    "matching final protocol-version request did not dispatch: {accepted:?}"
                ));
            }

            if !rejected.starts_with(b"HTTP/1.1 400") {
                return Err(format!(
                    "mismatched final protocol-version request did not return HTTP 400: {rejected:?}"
                ));
            }
            let rejected: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&rejected)?).map_err(|error| {
                    format!("rejected protocol-admission response was invalid: {error}")
                })?;
            if rejected.id != Some(814_i64.into())
                || rejected.result.is_some()
                || rejected.error.as_ref().map(|error| error.code)
                    != Some(fastmcp_protocol::HEADER_MISMATCH_ERROR_CODE)
                || rejected.error.as_ref().and_then(|error| error.data.as_ref()).is_some()
            {
                return Err(format!(
                    "mismatched final protocol-version request did not retain its canonical JSON-RPC error: {rejected:?}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_dual_accept_sse_streams_progress_log_and_terminal_frames() {
        run_live_http_test(|cx| async move {
            let calls = Arc::new(AtomicUsize::new(0));
            let bound = Server::new("live-modern-sse-frames", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .log_level(Level::Debug)
                .tool(HttpRequestScopedProgressTool {
                    calls: Arc::clone(&calls),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live modern SSE bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live modern SSE address failed: {error}"))?;
            let request = JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "http_request_scoped_progress",
                    "arguments": {},
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                        "progressToken": "live-http-progress",
                        "io.modelcontextprotocol/logLevel": "info",
                    },
                })),
                813_i64,
            );
            let body = serde_json::to_vec(&request)
                .map_err(|error| format!("live SSE request did not serialize: {error}"))?;
            let request = live_http_post(
                "/mcp",
                &body,
                &[
                    ("Accept", "application/json, text/event-stream; Q=1."),
                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                    ("Mcp-Method", "tools/call"),
                    ("Mcp-Name", "http_request_scoped_progress"),
                ],
            );
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let deadline = caller_cx
                        .now()
                        .saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
                    let mut stream =
                        asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
                            .await
                            .map_err(|_| {
                                live_http_test_timeout("live modern SSE client connection")
                            })?
                            .map_err(|error| format!("live modern SSE connect failed: {error}"))?;
                    asupersync::time::timeout_at(deadline, stream.write_all(&request))
                        .await
                        .map_err(|_| live_http_test_timeout("live modern SSE request write"))?
                        .map_err(|error| format!("live modern SSE write failed: {error}"))?;
                    asupersync::time::timeout_at(deadline, stream.flush())
                        .await
                        .map_err(|_| live_http_test_timeout("live modern SSE request flush"))?
                        .map_err(|error| format!("live modern SSE flush failed: {error}"))?;
                    let mut received = Vec::new();
                    read_live_http_until(&mut stream, &mut received, b"notifications/progress")
                        .await?;
                    read_live_http_until(&mut stream, &mut received, b"notifications/message")
                        .await?;
                    read_live_http_until(&mut stream, &mut received, b"\"id\":813").await?;
                    read_live_http_to_end(
                        &mut stream,
                        &mut received,
                        "live modern SSE terminal EOF",
                    )
                    .await?;
                    caller_cx.cancel_with(CancelKind::User, Some("modern SSE stream complete"));
                    Ok::<_, String>(received)
                })
                .map_err(|error| format!("live modern SSE client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let response = client
                .join(&cx)
                .await
                .map_err(|error| format!("live modern SSE client failed: {error:?}"))??;
            serve.map_err(|error| format!("live modern SSE server failed: {error}"))?;
            let response = std::str::from_utf8(&response)
                .map_err(|error| format!("live modern SSE response was not UTF-8: {error}"))?;
            if !response.starts_with("HTTP/1.1 200")
                || !response
                    .to_ascii_lowercase()
                    .contains("content-type: text/event-stream")
            {
                return Err(format!(
                    "live modern SSE response head was unexpected: {response}"
                ));
            }
            for required in [
                "notifications/progress",
                "notifications/message",
                "\"id\":813",
            ] {
                if !response.contains(required) {
                    return Err(format!("live modern SSE response omitted {required}"));
                }
            }
            if response.match_indices("data: ").count() < 3 {
                return Err("live modern SSE response collapsed request-scoped frames".to_owned());
            }
            if !response.ends_with("0\r\n\r\n") {
                return Err(
                    "live modern SSE response omitted the terminating chunk after its final response"
                        .to_owned(),
                );
            }
            if calls.load(Ordering::Acquire) != 1 {
                return Err("live modern SSE handler did not execute exactly once".to_owned());
            }
            Ok(())
        });
    }

