    #[test]
    fn returning_loop_replies_to_bounded_codec_error_then_reads_next_frame() {
        use std::collections::VecDeque;
        use std::sync::atomic::AtomicUsize;

        // A malformed OPENING frame is a fatal era-security rejection under
        // Auto, so the recoverable-parse-error contract is probed on an
        // already negotiated connection.
        let steps = Arc::new(Mutex::new(VecDeque::from([
            Ok(exact_legacy_initialize_request(32, serde_json::json!("1.0.0"))),
            Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/initialized",
                None,
            ))),
            Err(TransportError::Codec(fastmcp_transport::CodecError::Json(
                serde_json::from_str::<serde_json::Value>("{")
                    .expect_err("fixture must be invalid JSON"),
            ))),
            Err(TransportError::Closed),
        ])));
        let receive_calls = Arc::new(AtomicUsize::new(0));
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcMessage>::new()));
        let receive_steps = Arc::clone(&steps);
        let receive_count = Arc::clone(&receive_calls);
        let sent_messages = Arc::clone(&sent);

        Server::new("recoverable-codec-error-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_count.fetch_add(1, Ordering::Relaxed);
                    receive_steps
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .pop_front()
                        .unwrap_or(Err(TransportError::Closed))
                },
                move |_, message| {
                    sent_messages
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push(message.clone());
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect("clean transport closure after a recoverable codec error must succeed");

        assert_eq!(receive_calls.load(Ordering::Relaxed), 4);
        let sent = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // The initialize response races worker shutdown and is incidental;
        // the contract is exactly one uncorrelated parse-error reply.
        let parse_errors: Vec<&JsonRpcResponse> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response) if response.id.is_none() => Some(response),
                _ => None,
            })
            .collect();
        let [response] = parse_errors.as_slice() else {
            panic!("expected exactly one uncorrelated parse-error response");
        };
        assert_eq!(
            response.error.as_ref().map(|error| error.code),
            Some(-32700)
        );
        let wire = serde_json::to_value(response).expect("parse error response must serialize");
        assert!(wire.get("id").is_none());
    }

    #[test]
    fn returning_loop_correlates_invalid_request_only_when_codec_proves_unique_id() {
        use std::collections::VecDeque;

        let invalid = fastmcp_transport::Codec::new()
            .decode_complete_message(br#"{"jsonrpc":"2.1","method":"tools/list","id":"safe-id"}"#)
            .expect_err("wrong JSON-RPC version must be invalid");
        // A malformed OPENING frame is a fatal era-security rejection under
        // Auto, so the correlation contract is probed on an already
        // negotiated connection.
        let steps = Arc::new(Mutex::new(VecDeque::from([
            Ok(exact_legacy_initialize_request(31, serde_json::json!("1.0.0"))),
            Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/initialized",
                None,
            ))),
            Err(TransportError::Codec(invalid)),
            Err(TransportError::Closed),
        ])));
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcMessage>::new()));
        let receive_steps = Arc::clone(&steps);
        let sent_messages = Arc::clone(&sent);

        Server::new("correlated-invalid-request-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_steps
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .pop_front()
                        .unwrap_or(Err(TransportError::Closed))
                },
                move |_, message| {
                    sent_messages
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push(message.clone());
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect("clean transport closure after an invalid-request reply must succeed");

        let sent = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // The initialize response races worker shutdown and is incidental;
        // the contract is exactly one reply correlated to the proven id.
        let correlated: Vec<&JsonRpcResponse> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response)
                    if response.id == Some(RequestId::String("safe-id".to_string())) =>
                {
                    Some(response)
                }
                _ => None,
            })
            .collect();
        let [response] = correlated.as_slice() else {
            panic!("expected exactly one response correlated to the proven unique id");
        };
        assert_eq!(
            response.error.as_ref().map(|error| error.code),
            Some(i32::from(McpErrorCode::InvalidRequest))
        );
    }

    #[test]
    fn returning_loop_terminates_after_fatal_framing_error_without_logging_payload() {
        use std::sync::atomic::AtomicUsize;

        let receive_calls = Arc::new(AtomicUsize::new(0));
        let receive_count = Arc::clone(&receive_calls);
        let sent = Arc::new(AtomicUsize::new(0));
        let sent_count = Arc::clone(&sent);

        let error = Server::new("fatal-framing-error-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_count.fetch_add(1, Ordering::Relaxed);
                    Err(TransportError::Io(std::io::Error::new(
                        std::io::ErrorKind::InvalidData,
                        "SECRET_FRAMING_CANARY\r\nforged-log-line",
                    )))
                },
                move |_, _| {
                    sent_count.fetch_add(1, Ordering::Relaxed);
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect_err("fatal framing failure must propagate from the returning loop");

        assert_eq!(receive_calls.load(Ordering::Relaxed), 1);
        assert_eq!(sent.load(Ordering::Relaxed), 0);
        assert_eq!(error.code, McpErrorCode::InternalError);
        assert_eq!(
            error.data.as_ref().and_then(|data| data["kind"].as_str()),
            Some("pump_failure")
        );
        assert_eq!(
            classify_receive_error(&TransportError::Timeout),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::ReceiveDeadlineExceeded),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::ControlFrameTooLarge {
                size: 513,
                max: 512,
            }),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::Codec(
                fastmcp_transport::CodecError::MessageTooLarge(42)
            )),
            ReceiveErrorDisposition::Terminate
        );
    }

    #[test]
    fn receive_pump_terminates_each_fatal_transport_failure_without_retrying() {
        use std::sync::atomic::AtomicUsize;

        for error in [
            TransportError::Timeout,
            TransportError::ReceiveDeadlineExceeded,
            TransportError::ControlFrameTooLarge {
                size: 513,
                max: 512,
            },
            TransportError::Codec(fastmcp_transport::CodecError::MessageTooLarge(42)),
        ] {
            let error_label = format!("{error:?}");
            let receive_calls = Arc::new(AtomicUsize::new(0));
            let receive_count = Arc::clone(&receive_calls);
            let sent = Arc::new(AtomicUsize::new(0));
            let sent_count = Arc::clone(&sent);
            let mut next_error = Some(error);

            let exit_code = Server::new("fatal-receive-error-test", "1.0.0")
                .build()
                .run_loop_pump(
                    &Cx::for_testing(),
                    move |_, _worker_failed| {
                        receive_count.fetch_add(1, Ordering::Relaxed);
                        Err(next_error.take().unwrap_or(TransportError::Closed))
                    },
                    move |_, _| {
                        sent_count.fetch_add(1, Ordering::Relaxed);
                        Ok(())
                    },
                    Arc::new(|_| {}),
                    "test",
                );

            assert_eq!(exit_code, 1, "fatal error must fail: {error_label}");
            assert_eq!(
                receive_calls.load(Ordering::Relaxed),
                1,
                "fatal error must not be retried: {error_label}"
            );
            assert_eq!(
                sent.load(Ordering::Relaxed),
                0,
                "fatal error must not emit a response: {error_label}"
            );
        }
    }

