    #[test]
    fn final_runtime_suppresses_info_log_when_only_log_level_changes_to_warning() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("final-log-runtime", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .log_level(Level::Debug)
            .build_http_endpoint("http://final.test")
            .expect("modern endpoint must build");
        let mut session = endpoint
            .open_session(&cx)
            .expect("modern endpoint session must open");
        let request = JsonRpcRequest::new(
            "tools/list",
            Some(serde_json::json!({
                "_meta": {
                    MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                    FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    "io.modelcontextprotocol/logLevel": "warning",
                },
            })),
            91_i64,
        );
        let ServerHttpEndpointResponse::ModernSse(sse) = session
            .handle(
                &cx,
                HttpRequest::new(HttpMethod::Post, "/mcp")
                    .with_header("content-type", "application/json")
                    .with_header("accept", "text/event-stream")
                    .with_header("mcp-protocol-version", MODERN_PROTOCOL_VERSION)
                    .with_header("mcp-method", "tools/list")
                    .with_body(serde_json::to_vec(&request).expect("final request must encode")),
            )
            .expect("public modern request must dispatch")
        else {
            panic!("public modern request must return an SSE body");
        };
        assert!(
            matches!(
                Codec::new()
                    .decode_complete_message(
                        sse.recv_event(&cx)
                            .expect("request response must remain readable")
                            .data
                            .as_bytes(),
                    )
                    .expect("response must remain JSON-RPC"),
                JsonRpcMessage::Response(response)
                    if response.id == Some(91_i64.into()) && response.error.is_none()
            ),
            "changing only final logLevel from info to warning must suppress the info notification"
        );
        // The dispatch task owns the response sender, so a completed request
        // may legitimately close the body afterwards; the negative's
        // invariant is only that no suppressed notification was queued.
        assert!(
            !matches!(sse.pop_event(), Ok(Some(_))),
            "the log-level-only negative must leave no notification queued"
        );
    }

    #[test]
    fn final_subscription_http_peer_cancellation_removes_without_server_terminal_control() {
        let server = Arc::new(Server::new("final-listen-peer-cancel-test", "1.0.0").build());
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcRequest>::new()));
        let sent_for_sender = Arc::clone(&sent);
        let notification_sender: NotificationSender = Arc::new(move |notification| {
            sent_for_sender
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(notification);
        });
        let subscription_id = RequestId::Number(74);
        let metadata = OpenMetadata::try_from_entries([
            (
                "io.modelcontextprotocol/protocolVersion".to_owned(),
                serde_json::json!(MODERN_PROTOCOL_VERSION),
            ),
            (
                FINAL_CLIENT_CAPABILITIES_META_KEY.to_owned(),
                serde_json::json!({}),
            ),
        ])
        .expect("final request metadata must be valid");
        let params = serde_json::to_value(FinalSubscriptionsListenParams {
            meta: metadata,
            notifications: SubscriptionFilter {
                tools_list_changed: Some(true),
                ..SubscriptionFilter::default()
            },
        })
        .expect("final listen parameters must serialize");
        let request =
            JsonRpcRequest::new(SUBSCRIPTIONS_LISTEN, Some(params), subscription_id.clone());
        let inbound = InboundRequestContext::new(
            Cx::for_testing(),
            request_id_to_u64(Some(&subscription_id)),
            InboundRequestTransport::Http,
        );
        let request_cancellation = McpRequestCancellation::new();
        let canceller = {
            let sent = Arc::clone(&sent);
            let request_cancellation = request_cancellation.clone();
            std::thread::spawn(move || {
                for _ in 0..100 {
                    if !sent
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .is_empty()
                    {
                        request_cancellation.cancel();
                        return true;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                false
            })
        };
        let response = block_on(Arc::clone(&server).dispatch_with_protocol_policy_owned(
            ProtocolPolicy::ModernOnly,
            &inbound,
            request,
            Some(74),
            request_cancellation,
            None,
            notification_sender,
        ));

        assert!(
            canceller
                .join()
                .expect("peer cancellation helper must not panic"),
            "the listener must acknowledge before the peer can close it"
        );
        assert!(
            response.is_none(),
            "a peer-closed stream must not receive a result"
        );
        assert_eq!(
            sent.lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .len(),
            1,
            "changing only the terminal trigger to peer cancellation must not send server cancellation control",
        );
        assert!(
            server
                .final_subscriptions
                .inner
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .entries
                .is_empty(),
            "peer cancellation must release exactly its request-owned registry entry",
        );
    }

    #[test]
    fn final_subscription_termination_is_single_winner_and_idempotent() {
        let registry = Arc::new(FinalSubscriptionRegistry::default());
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcRequest>::new()));
        let sent_for_sender = Arc::clone(&sent);
        let sender: NotificationSender = Arc::new(move |notification| {
            sent_for_sender
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(notification);
        });
        let cancellation = McpRequestCancellation::new();
        let _lease = registry
            .open(
                RequestId::Number(881),
                SubscriptionFilter::default(),
                false,
                Some(881),
                cancellation.clone(),
                None,
                sender,
            )
            .expect("a final listen must register before termination");

        assert_eq!(registry.terminate(), 1);
        assert_eq!(registry.terminate(), 0);
        assert!(cancellation.is_cancel_requested());
        let sent = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        assert_eq!(sent.len(), 2, "one acknowledgement and one control only");
        assert!(matches!(
            ServerNotification::decode(&sent[1]),
            Ok(ServerNotification::Cancelled(_))
        ));
    }

    #[test]
    fn final_subscription_shutdown_receipt_waits_for_terminal_consumption() {
        let registry = Arc::new(FinalSubscriptionRegistry::default());
        let terminal_delivery = Arc::new(FinalSubscriptionTerminalDelivery::default());
        let sender_delivery = Arc::clone(&terminal_delivery);
        let sender: NotificationSender = Arc::new(move |notification| {
            if notification.method == "notifications/cancelled" {
                sender_delivery.mark_enqueued();
            }
        });
        let _lease = registry
            .open(
                RequestId::Number(887),
                SubscriptionFilter::default(),
                false,
                Some(887),
                McpRequestCancellation::new(),
                Some(Arc::clone(&terminal_delivery)),
                sender,
            )
            .expect("a final listen must register before termination");

        let receipt = registry.terminate_with_receipt();
        assert_eq!(receipt.terminated, 1);
        assert!(terminal_delivery.is_enqueued());
        assert!(
            !receipt.is_settled(),
            "queue admission alone must not masquerade as body consumption"
        );

        terminal_delivery.mark_drained();
        assert!(receipt.is_settled());
    }

    #[test]
    fn final_subscription_shutdown_receipt_fails_closed_after_backpressure_bound() {
        let registry = Arc::new(FinalSubscriptionRegistry::default());
        let terminal_delivery = Arc::new(FinalSubscriptionTerminalDelivery::default());
        let sender_delivery = Arc::clone(&terminal_delivery);
        let sender: NotificationSender = Arc::new(move |notification| {
            if notification.method == "notifications/cancelled" {
                sender_delivery.mark_enqueued();
            }
        });
        let _lease = registry
            .open(
                RequestId::Number(888),
                SubscriptionFilter::default(),
                false,
                Some(888),
                McpRequestCancellation::new(),
                Some(Arc::clone(&terminal_delivery)),
                sender,
            )
            .expect("a final listen must register before termination");

        let receipt = registry.terminate_with_receipt();
        assert!(!receipt.is_settled());
        receipt.fail_pending();
        assert!(
            receipt.is_settled(),
            "bounded shutdown must turn an unconsumed terminal into an explicit failure"
        );
        assert!(!terminal_delivery.is_drained());
    }

